dir:


































  &DefaultButton;




function dir$dmbgn(p){
  this.constructor(p);
}
dir$dmbgn.prototype = new DirEvent();
dir$dmbgn.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmbgn.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmbgnDisabledMasterField(p, g);

}

function dir$dmbgnDisabledMasterField(p, g){

  if(p.valForm('ma_bgn').trim() != '')
  {
    p.setDisabled('ma_bgn', true);
  }
  else
  {
    p.setDisabled('ma_bgn', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã điều kiện đã tồn tại' else N'List Of Shipping Lines is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã điều kiện đã tồn tại' else N'List Of Shipping Lines is exists' end
